/* Renders foundation token views from window.AEC_TOKENS (generated by scripts/build-tokens.mjs). */
(function () {
  'use strict';
  var T = window.AEC_TOKENS;
  var esc = window.DRS.esc;
  if (!T) return;

  // ---------- Contrast ----------
  function rgb(v) {
    if (v[0] === '#') { var n = parseInt(v.slice(1), 16); return [n >> 16 & 255, n >> 8 & 255, n & 255, 1]; }
    var m = v.match(/[\d.]+/g).map(Number); return [m[0], m[1], m[2], m[3] == null ? 1 : m[3]];
  }
  function lum(c) { var a = c.slice(0, 3).map(function (x) { x /= 255; return x <= 0.03928 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4); }); return 0.2126 * a[0] + 0.7152 * a[1] + 0.0722 * a[2]; }
  function ratio(a, b) { var l1 = lum(rgb(a)), l2 = lum(rgb(b)); return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05); }
  window.DRS.contrast = ratio;

  // ---------- Live brand values ----------
  // Foundation views show the values of the active brand (css/brands/<id>.css), falling back to the Figma JSON.
  function live(token) { return getComputedStyle(document.documentElement).getPropertyValue(token).trim(); }
  function toHex(v) {
    var m = String(v).match(/^rgba?\(([^)]+)\)$/);
    if (!m) return v;
    var p = m[1].split(/[\s,/]+/).filter(Boolean).map(Number);
    if (p.length > 3 && p[3] < 1) return v;
    return '#' + p.slice(0, 3).map(function (x) { return ('0' + Math.round(x).toString(16)).slice(-2); }).join('');
  }
  // Brand typography per breakpoint, read from the brand stylesheet rules
  function brandTypeVars() {
    var id = document.documentElement.getAttribute('data-brand');
    var link = document.querySelector('link[data-brand-css="' + id + '"]');
    var out = { base: {}, m768: {}, m1025: {} };
    if (!link || !link.sheet) return out;
    var read = function (rule, into) { for (var i = 0; i < rule.style.length; i++) { var n = rule.style[i]; if (n.indexOf('--aec-typography-') === 0) into[n] = rule.style.getPropertyValue(n).trim(); } };
    try {
      [].forEach.call(link.sheet.cssRules, function (r) {
        if (r.selectorText) read(r, out.base);
        else if (r.media) { var key = /1025/.test(r.media.mediaText) ? 'm1025' : /768/.test(r.media.mediaText) ? 'm768' : null; if (key) [].forEach.call(r.cssRules, function (x) { if (x.selectorText) read(x, out[key]); }); }
      });
    } catch (e) {}
    return out;
  }

  // ---------- Colour ----------
  function renderColour() {
  document.querySelectorAll('[data-swatches]').forEach(function (el) {
    var groups = el.getAttribute('data-swatches').split(',');
    var items = T.colors.filter(function (c) { return groups.indexOf(c.group) > -1; });
    var prefix = el.getAttribute('data-prefix');
    if (prefix) items = items.filter(function (c) { return c.figma.indexOf(prefix) === 0; });
    el.innerHTML = items.map(function (c) {
      c = Object.assign({}, c, { value: toHex(live(c.token)) || c.value });
      var solid = c.value[0] === '#';
      var onWhite = solid ? ratio(c.value, '#ffffff') : null;
      var onDark = solid ? ratio(c.value, '#262626') : null;
      var best = solid ? (onWhite >= onDark ? { r: onWhite, bg: 'white' } : { r: onDark, bg: 'text/default' }) : null;
      var meta = best ? '<span class="doc-contrast ' + (best.r >= 4.5 ? 'is-pass' : 'is-fail') + '" title="Contrast against ' + best.bg + '">' + best.r.toFixed(2) + ':1 ' + (best.r >= 4.5 ? 'AA' : best.r >= 3 ? 'AA large' : '') + '</span>' : '<span>Translucent</span>';
      return '<button type="button" class="doc-swatch" data-copy="var(' + c.token + ')" data-copy-label="' + c.token + '" aria-label="Copy ' + c.token + ' (' + c.value + ')">' +
        '<span class="doc-swatch-chip"><span class="doc-swatch-fill" style="background:var(' + c.token + ')"></span></span>' +
        '<span class="doc-swatch-body"><span class="doc-swatch-name">' + esc(c.figma) + '</span>' +
        '<span class="doc-swatch-token">' + esc(c.token) + '</span>' +
        '<span class="doc-swatch-meta"><span>' + esc(c.value) + '</span>' + meta + '</span></span></button>';
    }).join('');
  });
  }

  // ---------- Typography ----------
  function typeSpec(name) {
    var V = brandTypeVars(), k = '--aec-typography-' + name + '-';
    var pick = function (o) { var sz = o[k + 'font-size']; return sz ? [sz.replace('px', ''), (o[k + 'line-height'] || '').replace('px', ''), o[k + 'font-weight'], o[k + 'text-transform']] : null; };
    var m = pick(V.base), t = pick(V.m768), d = pick(V.m1025) || t || m;
    return { mobile: m, desktop: d || m, family: (V.base[k + 'font-family'] || '').split(',')[0].replace(/"/g, '') };
  }
  function fmt(x) { return x ? x[0] + '/' + x[1] + ' · weight ' + x[2] + (x[3] && x[3] !== 'none' ? ' · ' + x[3] : '') : ''; }
  function renderType() {
  document.querySelectorAll('[data-type-scale]').forEach(function (el) {
    var kind = el.getAttribute('data-type-scale');
    var sample = el.getAttribute('data-sample') || 'Build and price your new vehicle';
    el.innerHTML = T.typography.filter(function (t) { return t.name.indexOf(kind) === 0; }).map(function (t) {
      var sp = typeSpec(t.name);
      var d = sp.desktop, m = sp.mobile;
      if (!d) { d = t.desktop; m = t.mobile; }
      var cls = 'aec-' + t.name;
      var mob = m && d && m.join() !== d.join() ? '<br>Mobile ' + fmt(m) : '';
      return '<div class="doc-type-row"><div class="doc-type-meta"><strong>' + t.name.replace('-', ' ') + '</strong>' +
        (sp.desktop ? 'Desktop ' + fmt(d) : d[0] + '/' + d[1]) + mob + (sp.family ? '<br>' + esc(sp.family) : '') +
        '<br><button type="button" class="doc-btn" style="margin-top:8px" data-copy="' + cls + '" data-copy-label=".' + cls + '">.' + cls + '</button></div>' +
        '<div class="doc-type-sample ' + cls + '">' + esc(sample) + '</div></div>';
    }).join('');
  });

  document.querySelectorAll('[data-type-table]').forEach(function (el) {
    var rows = T.typography.map(function (t) {
      var sp = typeSpec(t.name);
      var d = sp.desktop || t.desktop, m = sp.mobile || t.mobile || t.desktop;
      return '<tr><td><code>.aec-' + t.name + '</code></td><td>' + d[0] + ' / ' + d[1] + '</td><td>' + m[0] + ' / ' + m[1] + '</td><td>' + d[2] + (m[2] !== d[2] ? ' (mobile ' + m[2] + ')' : '') + '</td><td>' + esc(sp.family || '') + '</td><td><code>--aec-typography-' + t.name + '-font-size</code></td></tr>';
    }).join('');
    el.innerHTML = '<table class="doc-table"><thead><tr><th>Class</th><th>Desktop (px)</th><th>Mobile (px)</th><th>Weight</th><th>Family</th><th>Size token</th></tr></thead><tbody>' + rows + '</tbody></table>';
  });
  }

  // ---------- Spacing / border / elevation ----------
  function renderMetrics() {
  document.querySelectorAll('[data-spacing]').forEach(function (el) {
    var parts = el.getAttribute('data-spacing').split('.');
    var items = T.spacing.filter(function (s) { return s.group === parts[0] && s.prop === parts[1]; }).map(function (s) { return Object.assign({}, s, { value: live(s.token) || s.value }); });
    el.innerHTML = items.map(function (s) {
      return '<div class="doc-token-row"><strong>' + s.size + ' · ' + s.value + '</strong><div class="doc-spacing-bar" style="width:' + s.value + '"></div>' +
        '<button type="button" class="doc-btn" data-copy="var(' + s.token + ')" data-copy-label="' + s.token + '"><code>' + s.token + '</code></button></div>';
    }).join('');
  });

  // ---------- Border ----------
  document.querySelectorAll('[data-radius]').forEach(function (el) {
    el.innerHTML = T.radius.map(function (r) { r = Object.assign({}, r, { value: live(r.token) || r.value });
      var shown = r.value === '384px' ? '999px' : r.value;
      return '<div class="doc-token-row"><div class="doc-radius-box" style="border-radius:' + shown + '"></div><div><strong>' + r.token.replace('--aec-border-radius-', '') + '</strong><div class="doc-muted doc-small">' + r.value + (r.alias ? ' · ' + r.alias : '') + '</div></div>' +
        '<button type="button" class="doc-btn" data-copy="var(' + r.token + ')" data-copy-label="' + r.token + '"><code>' + r.token + '</code></button></div>';
    }).join('');
  });
  document.querySelectorAll('[data-width]').forEach(function (el) {
    el.innerHTML = T.width.map(function (w) {
      return '<div class="doc-token-row"><div style="width:96px;height:40px;border-radius:8px;border:' + w.value + ' solid var(--aec-color-text-default)"></div><div><strong>' + w.token.replace('--aec-border-width-', '') + '</strong><div class="doc-muted doc-small">' + w.value + (w.alias ? ' · ' + w.alias : '') + '</div></div>' +
        '<button type="button" class="doc-btn" data-copy="var(' + w.token + ')" data-copy-label="' + w.token + '"><code>' + w.token + '</code></button></div>';
    }).join('');
  });

  // ---------- Elevation ----------
  var use = { none: 'Flat surfaces, inline content', xs: 'Subtle separation, inputs', s: 'Cards at rest, menus', m: 'Raised cards, hover', l: 'Dropdowns, popovers', xl: 'Sheets, toasts', '2xl': 'Modals and dialogs' };
  document.querySelectorAll('[data-shadows]').forEach(function (el) {
    el.innerHTML = T.shadow.map(function (s) {
      return '<button type="button" class="doc-shadow-card" style="box-shadow:var(' + s.token + ');border:0;text-align:left;font:inherit;cursor:pointer" data-copy="var(' + s.token + ')" data-copy-label="' + s.token + '"><strong>shadow/' + s.name + '</strong><span class="doc-muted">' + use[s.name] + '</span><code style="background:none;padding:0;margin-top:4px">' + s.token + '</code></button>';
    }).join('');
  });

  }

  function renderAll() { renderColour(); renderType(); renderMetrics(); }
  renderAll();
  document.addEventListener('drs:brand', renderAll);
  // the brand sheet may still be loading on first paint
  var bl = document.querySelector('link[data-brand-css]');
  if (bl && !bl.sheet) bl.addEventListener('load', renderAll);

  // ---------- Icons ----------
  var grid = document.querySelector('[data-icon-grid]');
  if (grid) {
    var ROOT = window.DRS.ROOT;
    var search = document.getElementById('icon-search');
    var sizeSel = document.getElementById('icon-size');
    var count = document.getElementById('icon-count');
    fetch(ROOT + 'assets/icons/icons.json').then(function (r) { return r.json(); }).then(function (data) {
      var all = data.icons || [];
      function draw() {
        var q = (search.value || '').trim().toLowerCase();
        var list = all.filter(function (i) { return !q || i.name.indexOf(q) > -1; });
        count.textContent = list.length + ' of ' + all.length + ' icons';
        grid.style.setProperty('--icon-size', sizeSel.value + 'px');
        grid.innerHTML = list.map(function (i) {
          return '<button type="button" class="doc-icon" data-copy="' + i.name + '" data-copy-label="Icon name ‘' + i.name + '’" title="' + esc(i.figma) + '">' +
            '<span class="aec-icon" style="--aec-icon-src:url(/' + i.file + ');width:var(--icon-size);height:var(--icon-size)" aria-hidden="true"></span><span>' + esc(i.name) + '</span></button>';
        }).join('') || '<p class="doc-muted">No icons match “' + esc(q) + '”.</p>';
      }
      search.addEventListener('input', draw);
      sizeSel.addEventListener('change', draw);
      draw();
    }).catch(function () { grid.innerHTML = '<p class="doc-muted">Icon manifest could not be loaded.</p>'; });
  }

  var ill = document.querySelector('[data-illustrations]');
  if (ill) {
    fetch(window.DRS.ROOT + 'assets/illustrations/illustrations.json').then(function (r) { return r.json(); }).then(function (data) {
      var list = Array.isArray(data) ? data : (data.illustrations || []);
      ill.innerHTML = list.map(function (i) {
        if (i.file.indexOf('/') < 0) i.file = 'assets/illustrations/' + i.file;
        i.name = i.name.replace(/-illustration$/i, '').replace(/-/g, ' ');
        return '<figure class="doc-card" style="margin:0"><div class="doc-card-art" style="height:160px;background:#fff"><img src="' + window.DRS.ROOT + i.file + '" alt="" style="max-height:120px;max-width:80%"></div><h3>' + esc(i.name) + '</h3><p><a href="' + window.DRS.ROOT + i.file + '" download>Download SVG</a></p></figure>';
      }).join('');
    }).catch(function () { ill.innerHTML = '<p class="doc-muted">Illustrations could not be loaded.</p>'; });
  }
})();
